								<button
									type="button"
									class="flex h-9 w-9 items-center justify-center rounded-full text-ui-ink-gray-600 hover:bg-ui-surface-gray-100"
									aria-label="Bulan berikutnya"
									@click="nextMonth"
								>
									<svg
										xmlns="http://www.w3.org/2000/svg"
										viewBox="0 0 24 24"
										class="h-5 w-5"
										fill="none"
										stroke="currentColor"
										stroke-width="2"
										stroke-linecap="round"
										stroke-linejoin="round"
									>
										<path d="m9 18 6-6-6-6" />
									</svg>
								</button>
							</div>

							<!-- Grid kalender -->
							<div class="grid grid-cols-7 gap-y-1 text-center">
								<div
									v-for="w in WEEKDAYS"
									:key="w"
									class="py-1.5 text-xs font-semibold text-ui-ink-gray-400"
								>
									{{ w }}
								</div>
								<div v-for="(cell, i) in calDays" :key="i" class="py-0.5">
									<button
										v-if="cell"
										type="button"
										class="mx-auto flex h-9 w-9 items-center justify-center text-xs transition"
										:class="dayClass(cell)"
										@click="pickDay(cell)"
									>
										{{ cell.getDate() }}
									</button>
								</div>
							</div>

							<!-- Ringkasan rentang -->
							<div class="mt-3 flex items-center justify-center gap-2 text-xs">
								<span
									class="rounded-lg bg-ui-surface-gray-100 px-3 py-1.5 font-medium"
									:class="
										rangeStart
											? 'text-ui-ink-gray-800'
											: 'text-ui-ink-gray-400'
									"
								>
									{{ rangeStart ? formatDate(rangeStart) : 'Mulai' }}
								</span>
								<span class="text-ui-ink-gray-400">→</span>
								<span
									class="rounded-lg bg-ui-surface-gray-100 px-3 py-1.5 font-medium"
									:class="
										rangeEnd ? 'text-ui-ink-gray-800' : 'text-ui-ink-gray-400'
									"
								>
									{{ rangeEnd ? formatDate(rangeEnd) : 'Akhir' }}
								</span>
							</div>

							<div class="mt-5 flex items-center gap-3">
								<button
									type="button"
									class="w-full rounded-full border border-ui-line-gray-300 py-3.5 text-xs font-semibold text-ui-ink-gray-700 transition active:scale-[0.98]"
									@click="clearDateRange"
								>
									Reset
								</button>
								<button
									type="button"
									class="w-full rounded-full bg-primary py-3.5 text-xs font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.98]"
									@click="applyDateRange"
								>
									Terapkan
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { ref, reactive, computed, watch, onUnmounted } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { createResource } from 'frappe-ui'
import { fidFpdConfig } from '../config/fidFpdTypes'
import { useListPersistence } from '../composables/useListPersistence'

const props = defineProps({
	// 'fid' | 'fpd' | 'fid_cutoff' | 'fpd_cutoff'
	type: { type: String, default: 'fid' },
})

const router = useRouter()
const route = useRoute()
const cfg = computed(() => fidFpdConfig(props.type))
const title = computed(() => cfg.value.title)

// Konteks marketing terpilih (Pimcab dari List Marketing). m = id_marketing.
const selectedMarketing = computed(() => String(route.query.m || ''))
const selectedMarketingName = computed(() => String(route.query.nm || ''))
const listPersistence = useListPersistence(
	() => `${route.name || props.type}:marketing=${selectedMarketing.value}`,
)
const marketingQuery = computed(() => {
	const q = {}
	if (selectedMarketing.value) q.m = selectedMarketing.value
	if (selectedMarketingName.value) q.nm = selectedMarketingName.value
	return q
})

// Klik baris → buka halaman detail (route name beda per tipe). Bawa konteks
// marketing agar detail ikut terkunci ke marketing yang sama.
function openDetail(row) {
	router.push({
		name: cfg.value.detailRoute,
		params: { name: row.name },
		query: marketingQuery.value,
	})
}

// Kembali ke halaman pemilih FID/FPD (pertahankan konteks marketing).
function goBack() {
	router.push({ name: 'FidFpdChooser', query: marketingQuery.value })
}

// ===== Field untuk Sort (bottom-sheet, gaya Data Pengajuan) =====
const SORT_FIELDS = [
	{ key: 'jto_cicilan', label: 'Tanggal JTO' },
	{ key: 'nama_nasabah', label: 'Nama Nasabah' },
	{ key: 'no_perjanjian', label: 'No Perjanjian' },
]

// ===== State data =====
const pageLength = ref(20)
const rows = ref([])
const total = ref(null)
const start = ref(0)
const hasMore = ref(true)
const initialLoading = ref(true)
const loadingMore = ref(false)

// ===== Sort (bottom-sheet, gaya Data Pengajuan) =====
const sortField = ref('jto_cicilan')
const sortDir = ref('desc')
const showSortSheet = ref(false)
const sortFieldDraft = ref(sortField.value)
const sortDirDraft = ref(sortDir.value)
function openSort() {
	sortFieldDraft.value = sortField.value
	sortDirDraft.value = sortDir.value
	showSortSheet.value = true
}
function pickSortField(key) {
	sortFieldDraft.value = key
}
function toggleSortDirDraft() {
	sortDirDraft.value = sortDirDraft.value === 'asc' ? 'desc' : 'asc'
}
function applySort() {
	sortField.value = sortFieldDraft.value
	sortDir.value = sortDirDraft.value
	listPersistence.writePreferences({ sortField: sortField.value, sortDir: sortDir.value })
	showSortSheet.value = false
	reload()
}

// ===== Filter (bottom-sheet, gaya Data Pengajuan) =====
// Tanggal JTO sebagai RENTANG (dari–sampai), sama seperti Tanggal Pengajuan di
// Data Pengajuan. Backend memfilter pakai >= / <=.
function blankFilter() {
	return {
		nama_nasabah: '',
		no_perjanjian: '',
		nopol: '',
		nama_marketing: '',
		tanggal_dari: '',
		tanggal_sampai: '',
	}
}
const filterDraft = reactive(blankFilter()) // working copy saat sheet terbuka
const appliedFilter = reactive(blankFilter()) // yang sudah diterapkan ke query
const showFilterSheet = ref(false)

// Jumlah field filter aktif → badge angka di ikon Filter.
const activeFilterCount = computed(() => {
	const f = appliedFilter
	let n = 0
	if (f.nama_nasabah.trim()) n++
	if (f.no_perjanjian.trim()) n++
	if (f.nopol.trim()) n++
	if (f.nama_marketing.trim()) n++
	if (f.tanggal_dari || f.tanggal_sampai) n++
	return n
})

// Buka sheet → salin filter terapan ke draft.
function openFilter() {
	Object.assign(filterDraft, { ...appliedFilter })
	showFilterSheet.value = true
}
function applyFilter() {
	Object.assign(appliedFilter, { ...filterDraft })
	listPersistence.writeSession({ filters: appliedFilter })
	showFilterSheet.value = false
	reload()
}
function clearFilter() {
	Object.assign(filterDraft, blankFilter())
	Object.assign(appliedFilter, blankFilter())
	listPersistence.clearSession()
	showFilterSheet.value = false
	reload()
}

// Filter AND yang dikirim ke API.
function buildFilters() {
	const out = []
	const f = appliedFilter
	if (f.nama_nasabah.trim()) out.push(['nama_nasabah', 'like', `%${f.nama_nasabah.trim()}%`])
	if (f.no_perjanjian.trim()) out.push(['no_perjanjian', 'like', `%${f.no_perjanjian.trim()}%`])
	if (f.nopol.trim()) out.push(['nopol', 'like', `%${f.nopol.trim()}%`])
	if (f.nama_marketing.trim())
		out.push(['nama_marketing', 'like', `%${f.nama_marketing.trim()}%`])
	// Rentang Tanggal JTO → >= dan/atau <= (backend tak punya 'between').
	if (f.tanggal_dari) out.push(['jto_cicilan', '>=', f.tanggal_dari])
	if (f.tanggal_sampai) out.push(['jto_cicilan', '<=', f.tanggal_sampai])
	return out
}

// ===== Kalender rentang Tanggal JTO (sama persis Data Pengajuan) =====
const showDateSheet = ref(false)
const calCursor = ref(new Date()) // bulan yang ditampilkan (tgl 1)
const rangeStart = ref('') // 'YYYY-MM-DD'
const rangeEnd = ref('')

const WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]

// Format lokal 'YYYY-MM-DD' (hindari pergeseran zona waktu dari toISOString).
function ymd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function parseYmd(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}

// Ringkasan rentang untuk field di sheet filter.
const dateSummary = computed(() => {
	const a = filterDraft.tanggal_dari
	const b = filterDraft.tanggal_sampai
	if (a && b) return `${formatDate(a)} – ${formatDate(b)}`
	if (a) return `Dari ${formatDate(a)}`
	if (b) return `Sampai ${formatDate(b)}`
	return ''
})

function openDateSheet() {
	rangeStart.value = filterDraft.tanggal_dari
	rangeEnd.value = filterDraft.tanggal_sampai
	const base = filterDraft.tanggal_dari || ymd(new Date())
	const d = parseYmd(base)
	calCursor.value = new Date(d.getFullYear(), d.getMonth(), 1)
	showDateSheet.value = true
}

const calLabel = computed(
	() => `${MONTHS[calCursor.value.getMonth()]} ${calCursor.value.getFullYear()}`,
)

// Sel kalender bulan aktif; null = padding awal pekan (mulai Senin).
const calDays = computed(() => {
	const year = calCursor.value.getFullYear()
	const month = calCursor.value.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7 // Senin = 0
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})

function prevMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() - 1, 1)
}
function nextMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() + 1, 1)
}

// Tap tanggal: tentukan mulai, lalu akhir (auto-tukar bila terbalik).
function pickDay(date) {
	const s = ymd(date)
	if (!rangeStart.value || (rangeStart.value && rangeEnd.value)) {
		rangeStart.value = s
		rangeEnd.value = ''
	} else if (s < rangeStart.value) {
		rangeEnd.value = rangeStart.value
		rangeStart.value = s
	} else {
		rangeEnd.value = s
	}
}

// Kelas tampilan tiap sel (endpoint / dalam rentang / hari ini / biasa).
function dayClass(date) {
	const s = ymd(date)
	const isStart = s === rangeStart.value
	const isEnd = s === rangeEnd.value
	if (isStart || isEnd) return 'rounded-full bg-primary font-semibold text-ui-onPrimary'
	if (rangeStart.value && rangeEnd.value && s > rangeStart.value && s < rangeEnd.value)
		return 'rounded-md bg-primary/10 text-primary'
	if (s === ymd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}

function clearDateRange() {
	rangeStart.value = ''
	rangeEnd.value = ''
}
// Simpan rentang ke draft (tetap di sheet filter setelah ini).
function applyDateRange() {
	filterDraft.tanggal_dari = rangeStart.value
	filterDraft.tanggal_sampai = rangeEnd.value
	showDateSheet.value = false
}

const orderBy = computed(() => `${sortField.value} ${sortDir.value}`)

const listResource = createResource({
	url: 'juragan.api.portal.fid_fpd.get_fid_fpd_list',
	method: 'GET',
	auto: false,
	makeParams() {
		const params = {
			type: props.type,
			start: start.value,
			page_length: pageLength.value,
			filters: JSON.stringify(buildFilters()),
			order_by: orderBy.value,
		}
		// Hanya sertakan saat ada pilihan marketing — jangan kirim "undefined".
		if (selectedMarketing.value) params.id_marketing = selectedMarketing.value
		return params
	},
	onSuccess(data) {
		const items = Array.isArray(data?.rows) ? data.rows : Array.isArray(data) ? data : []
		rows.value = start.value === 0 ? items : [...rows.value, ...items]
		hasMore.value = items.length === pageLength.value
		if (start.value === 0 && data && typeof data.total === 'number') total.value = data.total
		start.value += items.length
		initialLoading.value = false
		loadingMore.value = false
	},
	onError() {
		initialLoading.value = false
		loadingMore.value = false
		hasMore.value = false
	},
})

function reload() {
	start.value = 0
	hasMore.value = true
	initialLoading.value = true
	clearSelection()
	listResource.fetch()
}
function loadMore() {
	if (!hasMore.value || loadingMore.value) return
	loadingMore.value = true
	listResource.fetch()
}

// Reload otomatis saat ganti tipe / marketing. Sort & Filter reload eksplisit
// (lewat Terapkan di bottom-sheet masing-masing).
const queryKey = computed(() => JSON.stringify({ t: props.type, m: selectedMarketing.value }))
let reloadTimer
watch(queryKey, () => {
	clearTimeout(reloadTimer)
	restoreListState()
	reloadTimer = setTimeout(reload, 350)
})
onUnmounted(() => {
	clearTimeout(reloadTimer)
})

// ===== Selection =====
const listRef = ref(null)
const selectedKeys = ref([])
const selectedCount = computed(() => selectedKeys.value.length)
function clearSelection() {
	listRef.value?.toggleAllRows?.(false)
	selectedKeys.value = []
}

// ===== Helpers =====
const ID_MONTHS = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'Mei',
	'Jun',
	'Jul',
	'Agu',
	'Sep',
	'Okt',
	'Nov',
	'Des',
]
function formatDate(d) {
	if (!d) return '-'
	const [y, m, day] = String(d).split('-')
	if (!y || !m || !day) return d
	return `${day} ${ID_MONTHS[Number(m) - 1] || m} ${y}`
}
function initials(name) {
	if (!name) return '?'
	return name.trim()[0]?.toUpperCase() || '?'
}

// Muat pertama kali. Perubahan `type` setelah ini ditangani queryKey watcher
// (type ikut di dalam queryKey). SENGAJA paling akhir agar semua state sudah
// terinisialisasi sebelum reload() pertama (hindari TDZ).
function restoreListState() {
	Object.assign(appliedFilter, listPersistence.readSession({ filters: blankFilter() }).filters)
	const prefs = listPersistence.readPreferences({ sortField: 'jto_cicilan', sortDir: 'desc' })
	if (SORT_FIELDS.some((field) => field.key === prefs.sortField))
		sortField.value = prefs.sortField
	if (['asc', 'desc'].includes(prefs.sortDir)) sortDir.value = prefs.sortDir
}
restoreListState()
reload()
</script>

<style>
/* Ukuran font dikontrol lewat class Tailwind (text-*) langsung di elemen —
   tidak ada aturan CSS di sini yang memaksa/menimpa font-size. Class .dp-*
   di bawah hanya mengatur layout/warna field, bukan ukuran font. */

/* Field baris pada bottom-sheet Filter — border melingkupi ikon + input;
   abu-abu default, biru saat fokus (sama persis Data Pengajuan). */
.dp-field {
	@apply flex w-full items-center gap-3 rounded-2xl border border-ui-line-gray-300 px-4 py-3.5 transition;
}
.dp-field-input {
	@apply w-full border-0 bg-transparent p-0 text-ui-ink-gray-800 placeholder-ui-ink-gray-500 caret-primary outline-none focus:ring-0;
}
.dp-field-ic {
	@apply h-5 w-5 shrink-0 text-ui-ink-gray-500;
}
.dp-field-chev {
	@apply h-4 w-4 shrink-0 text-ui-ink-gray-500;
}
</style>
